<script setup lang="ts">
/**
 * AppShell.UserCard: the rail’s foot, showing the signed-in user.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Avatar from '../structure/Avatar.vue'

export interface AppShellUserCardProps {
  /**
   * The first line. Initials and the identity colour are derived from it.
   */
  name: string
  /**
   * The second line, such as an email, a role or the signed-in workspace.
   */
  detail: string
  /**
   * The avatar image.
   */
  src?: string
}

defineOptions({ name: 'AppShellUserCard', inheritAttrs: false })

defineProps<AppShellUserCardProps>()
defineSlots<{ end?: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <div :class="styles.userCard">
    <Avatar :name="name" :src="src" size="md" />
    <!-- userText -->
    <span :class="styles.userText">
      <span :class="styles.userName">
        {{ name }}
      </span>
      <span :class="styles.userDetail">
        {{ detail }}
      </span>
    </span>
    <!-- userEnd -->
    <span v-if="$slots.end" :class="styles.userEnd">
      <slot name="end" />
    </span>
  </div>
</template>
